/* Shaders of the picture settings (totk_post.h), compiled at run time like the other passes in nvn_mtl.m. Our own
   code except where a comment names the origin: SMAA 1x (MIT) and FidelityFX CAS (MIT), see THIRD_PARTY_NOTICES.md. */
static const char k_post_msl[] =
    "#include <metal_stdlib>\n"
    "using namespace metal;\n"
    "/* k.rt = (1/w, 1/h, w, h) of the source; k.rect = valid source region in pixels (x0, y0, x1, y1); k.p.x = CAS sharpness */\n"
    "struct K { float4 rt; float4 rect; float4 p; };\n"
    "struct V { float4 pos [[position]]; };\n"
    "vertex V pp_vs(uint id [[vertex_id]]) { float2 uv = float2((id << 1) & 2, id & 2); V o; o.pos = float4(uv * float2(2, -2) + float2(-1, 1), 0, 1); return o; }\n"
    "constexpr sampler lin(filter::linear, address::clamp_to_edge), pnt(filter::nearest, address::clamp_to_edge);\n"
    "static float2 uvc(float2 px, constant K &k) { return clamp(px, k.rect.xy + 0.5, k.rect.zw - 0.5) * k.rt.xy; }   // a pixel centre inside the valid region\n"
    "static float luma(float3 c) { return dot(saturate(c), float3(0.2126, 0.7152, 0.0722)); }   // display values; highlights above 1 count as 1\n"
    "static float4 tap(texture2d<float> t, float2 px, constant K &k) { return t.sample(pnt, uvc(px, k), level(0)); }\n"
    "\n"
    "fragment float4 pp_copy(V in [[stage_in]], texture2d<float> c [[texture(0)]], constant K &k [[buffer(0)]]) { return tap(c, in.pos.xy, k); }\n"
    "/* The UI-layer composite (totk_ui_layer.h). ui_squeeze: the premultiplied UI layer as one picture, narrowed by k.p.x and\n"
    "   flattened by k.p.y about the centre; outside it the layer's outermost texels carry on to the edges (a fade or a\n"
    "   full-screen backdrop still covers everything, an empty edge stays empty). ui_over: that UI over the scene, 1:1. */\n"
    "fragment float4 ui_squeeze(V in [[stage_in]], texture2d<float> u [[texture(0)]], constant K &k [[buffer(0)]]) {\n"
    "    float2 s = 0.5 + (in.pos.xy * k.rt.xy - 0.5) * k.p.xy;\n"
    "    return u.sample(lin, clamp(s, 0.5 * k.rt.xy, 1.0 - 0.5 * k.rt.xy), level(0));\n"
    "}\n"
    "fragment float4 ui_over(V in [[stage_in]], texture2d<float> u [[texture(0)]], texture2d<float> sc [[texture(1)]]) {\n"
    "    uint2 p = uint2(in.pos.xy); float4 a = u.read(p), b = sc.read(p);\n"
    "    return float4(a.rgb + (1.0 - a.a) * b.rgb, a.a + (1.0 - a.a) * b.a);\n"
    "}\n"
    "/* Bloom strength: drawn with blending zero + target * blend colour, so the target is scaled in place. */\n"
    "fragment float4 pp_zero(V in [[stage_in]]) { return float4(0); }\n"
    "\n"
    "/* Our FXAA: luma contrast test on the 3x3 neighbourhood, the edge's orientation from second differences, a walk along\n"
    "   the edge in both directions to its ends, and one bilinear tap shifted across the edge by the coverage estimate\n"
    "   (the larger of the end-distance blend and a sub-pixel aliasing term). Written for this port. */\n"
    "fragment float4 pp_fxaa(V in [[stage_in]], texture2d<float> c [[texture(0)]], constant K &k [[buffer(0)]]) {\n"
    "    float2 p = in.pos.xy;\n"
    "    float4 m = tap(c, p, k);\n"
    "    float lm = luma(m.rgb), ln = luma(tap(c, p + float2(0, -1), k).rgb), ls = luma(tap(c, p + float2(0, 1), k).rgb);\n"
    "    float le = luma(tap(c, p + float2(1, 0), k).rgb), lw = luma(tap(c, p + float2(-1, 0), k).rgb);\n"
    "    float hi = max(max(max(ln, ls), max(le, lw)), lm), lo = min(min(min(ln, ls), min(le, lw)), lm), range = hi - lo;\n"
    "    if (range < max(0.0312, hi * 0.125)) return m;\n"
    "    float lne = luma(tap(c, p + float2(1, -1), k).rgb), lnw = luma(tap(c, p + float2(-1, -1), k).rgb);\n"
    "    float lse = luma(tap(c, p + float2(1, 1), k).rgb), lsw = luma(tap(c, p + float2(-1, 1), k).rgb);\n"
    "    float avg = (2 * (ln + ls + le + lw) + lne + lnw + lse + lsw) / 12;\n"
    "    float sub = saturate(abs(avg - lm) / range); sub = sub * sub * (3 - 2 * sub); sub = sub * sub * 0.75;\n"
    "    float gh = abs(lnw - 2 * lw + lsw) + 2 * abs(ln - 2 * lm + ls) + abs(lne - 2 * le + lse);   // change across rows: a horizontal edge\n"
    "    float gv = abs(lnw - 2 * ln + lne) + 2 * abs(lw - 2 * lm + le) + abs(lsw - 2 * ls + lse);\n"
    "    bool horz = gh >= gv;\n"
    "    float l1 = horz ? ln : lw, l2 = horz ? ls : le, g1 = abs(l1 - lm), g2 = abs(l2 - lm);\n"
    "    float2 across = horz ? float2(0, 1) : float2(1, 0), along = horz ? float2(1, 0) : float2(0, 1);\n"
    "    float side = g1 >= g2 ? -1 : 1;   // the neighbour across the edge with the larger step\n"
    "    float lpair = 0.5 * (lm + (g1 >= g2 ? l1 : l2)), grad = 0.25 * max(g1, g2);\n"
    "    float2 e = p + across * side * 0.5;   // on the edge between the two rows\n"
    "    float2 a = e, b = e; float da = 0, db = 0, ea = 0, eb = 0; bool doneA = false, doneB = false;\n"
    "    const float steps[10] = {1, 1, 1, 1, 1.5, 2, 2, 2, 4, 8};\n"
    "    for (int i = 0; i < 10 && !(doneA && doneB); i++) {\n"
    "        if (!doneA) { a -= along * steps[i]; ea = luma(c.sample(lin, uvc(a, k), level(0)).rgb) - lpair; doneA = abs(ea) >= grad; }\n"
    "        if (!doneB) { b += along * steps[i]; eb = luma(c.sample(lin, uvc(b, k), level(0)).rgb) - lpair; doneB = abs(eb) >= grad; }\n"
    "    }\n"
    "    da = dot(p - a, along); db = dot(b - p, along);\n"
    "    bool nearA = da < db; float dn = min(da, db), span = da + db;\n"
    "    bool mBelow = lm - lpair < 0, endOk = ((nearA ? ea : eb) < 0) != mBelow;\n"
    "    float blend = endOk ? 0.5 - dn / span : 0;\n"
    "    float off = max(blend, sub);\n"
    "    return c.sample(lin, uvc(p + across * side * off, k), level(0));\n"
    "}\n"
    "\n"
    "/* FidelityFX CAS (AMD, MIT; see THIRD_PARTY_NOTICES.md), sharpen only (no scaling), CAS_BETTER_DIAGONALS and exact\n"
    "   rcp / sqrt; the weight uses the green channel only, as the reference does. k.p.x = -1 / lerp(8, 5, sharpness). */\n"
    "fragment float4 pp_cas(V in [[stage_in]], texture2d<float> t [[texture(0)]], constant K &k [[buffer(0)]]) {\n"
    "    float2 sp = in.pos.xy;\n"
    "    float3 a = saturate(tap(t, sp + float2(-1, -1), k).rgb), b = saturate(tap(t, sp + float2(0, -1), k).rgb), c = saturate(tap(t, sp + float2(1, -1), k).rgb);\n"
    "    float3 d = saturate(tap(t, sp + float2(-1, 0), k).rgb); float4 e4 = tap(t, sp, k); float3 e = saturate(e4.rgb), f = saturate(tap(t, sp + float2(1, 0), k).rgb);\n"
    "    float3 g = saturate(tap(t, sp + float2(-1, 1), k).rgb), h = saturate(tap(t, sp + float2(0, 1), k).rgb), i = saturate(tap(t, sp + float2(1, 1), k).rgb);\n"
    "    float3 mn = min(min(min(d, e), min(f, b)), h), mn2 = min(min(min(mn, a), min(c, g)), i); mn += mn2;\n"
    "    float3 mx = max(max(max(d, e), max(f, b)), h), mx2 = max(max(max(mx, a), max(c, g)), i); mx += mx2;\n"
    "    float3 amp = sqrt(saturate(min(mn, 2.0 - mx) / mx));\n"
    "    float w = amp.g * k.p.x;\n"
    "    return float4(saturate((b * w + d * w + f * w + h * w + e) / (1.0 + 4.0 * w)), e4.a);\n"
    "}\n"
    "\n"
    "/* ---- SMAA 1x (Jimenez et al., MIT; see THIRD_PARTY_NOTICES.md): luma edge detection, blending weights with diagonal\n"
    "   and corner detection, neighbourhood blending. Ported from SMAA.hlsl at the HIGH preset; the area texture holds only\n"
    "   the first 81 rows (sub-sample offset 0, all SMAA 1x reads). ---- */\n"
    "#define SMAA_THRESHOLD 0.1\n"
    "#define SMAA_MAX_SEARCH_STEPS 16\n"
    "#define SMAA_MAX_SEARCH_STEPS_DIAG 8\n"
    "#define SMAA_CORNER_ROUNDING 25\n"
    "#define SMAA_LOCAL_CONTRAST_ADAPTATION_FACTOR 2.0\n"
    "#define SMAA_AREATEX_MAX_DISTANCE 16\n"
    "#define SMAA_AREATEX_MAX_DISTANCE_DIAG 20\n"
    "#define SMAA_AREATEX_PIXEL_SIZE (1.0 / float2(160.0, 81.0))\n"
    "#define SMAA_SEARCHTEX_SIZE float2(66.0, 33.0)\n"
    "#define SMAA_SEARCHTEX_PACKED_SIZE float2(64.0, 16.0)\n"
    "#define SMAA_CORNER_ROUNDING_NORM (float(SMAA_CORNER_ROUNDING) / 100.0)\n"
    "#define RT k.rt\n"
    "static float4 lz(texture2d<float> t, float2 uv) { return t.sample(lin, uv, level(0)); }\n"
    "static float4 lzo(texture2d<float> t, float2 uv, int2 o, constant K &k) { return t.sample(lin, uv + float2(o) * RT.xy, level(0)); }\n"
    "static float2 step2(float e, float2 x) { return step(float2(e), x); }\n"
    "\n"
    "fragment float2 smaa_edge(V in [[stage_in]], texture2d<float> colorTex [[texture(0)]], constant K &k [[buffer(0)]]) {\n"
    "    float2 px = in.pos.xy;\n"
    "    float L = luma(tap(colorTex, px, k).rgb), Lleft = luma(tap(colorTex, px + float2(-1, 0), k).rgb), Ltop = luma(tap(colorTex, px + float2(0, -1), k).rgb);\n"
    "    float4 delta; delta.xy = abs(L - float2(Lleft, Ltop));\n"
    "    float2 edges = step2(SMAA_THRESHOLD, delta.xy);\n"
    "    if (dot(edges, float2(1.0)) == 0.0) discard_fragment();\n"
    "    float Lright = luma(tap(colorTex, px + float2(1, 0), k).rgb), Lbottom = luma(tap(colorTex, px + float2(0, 1), k).rgb);\n"
    "    delta.zw = abs(L - float2(Lright, Lbottom));\n"
    "    float2 maxDelta = max(delta.xy, delta.zw);\n"
    "    float Lleftleft = luma(tap(colorTex, px + float2(-2, 0), k).rgb), Ltoptop = luma(tap(colorTex, px + float2(0, -2), k).rgb);\n"
    "    delta.zw = abs(float2(Lleft, Ltop) - float2(Lleftleft, Ltoptop));\n"
    "    maxDelta = max(maxDelta.xy, delta.zw);\n"
    "    float finalDelta = max(maxDelta.x, maxDelta.y);\n"
    "    edges.xy *= step(finalDelta, SMAA_LOCAL_CONTRAST_ADAPTATION_FACTOR * delta.xy);\n"
    "    return edges;\n"
    "}\n"
    "\n"
    "static float2 decodeDiag(float2 e) { e.r = e.r * abs(5.0 * e.r - 5.0 * 0.75); return round(e); }\n"
    "static float4 decodeDiag(float4 e) { e.rb = e.rb * abs(5.0 * e.rb - 5.0 * 0.75); return round(e); }\n"
    "static float2 searchDiag1(texture2d<float> edgesTex, float2 texcoord, float2 dir, thread float2 &e, constant K &k) {\n"
    "    float4 coord = float4(texcoord, -1.0, 1.0); float3 t = float3(RT.xy, 1.0);\n"
    "    while (coord.z < float(SMAA_MAX_SEARCH_STEPS_DIAG - 1) && coord.w > 0.9) {\n"
    "        coord.xyz = t * float3(dir, 1.0) + coord.xyz;\n"
    "        e = lz(edgesTex, coord.xy).rg;\n"
    "        coord.w = dot(e, float2(0.5));\n"
    "    }\n"
    "    return coord.zw;\n"
    "}\n"
    "static float2 searchDiag2(texture2d<float> edgesTex, float2 texcoord, float2 dir, thread float2 &e, constant K &k) {\n"
    "    float4 coord = float4(texcoord, -1.0, 1.0);\n"
    "    coord.x += 0.25 * RT.x;\n"
    "    float3 t = float3(RT.xy, 1.0);\n"
    "    while (coord.z < float(SMAA_MAX_SEARCH_STEPS_DIAG - 1) && coord.w > 0.9) {\n"
    "        coord.xyz = t * float3(dir, 1.0) + coord.xyz;\n"
    "        e = lz(edgesTex, coord.xy).rg;\n"
    "        e = decodeDiag(e);\n"
    "        coord.w = dot(e, float2(0.5));\n"
    "    }\n"
    "    return coord.zw;\n"
    "}\n"
    "static float2 areaDiag(texture2d<float> areaTex, float2 dist, float2 e) {\n"
    "    float2 texcoord = float2(SMAA_AREATEX_MAX_DISTANCE_DIAG) * e + dist;\n"
    "    texcoord = SMAA_AREATEX_PIXEL_SIZE * texcoord + 0.5 * SMAA_AREATEX_PIXEL_SIZE;\n"
    "    texcoord.x += 0.5;\n"
    "    return lz(areaTex, texcoord).rg;\n"
    "}\n"
    "static float2 diagWeights(texture2d<float> edgesTex, texture2d<float> areaTex, float2 texcoord, float2 e, constant K &k) {\n"
    "    float2 weights = float2(0.0);\n"
    "    float4 d; float2 end;\n"
    "    if (e.r > 0.0) { d.xz = searchDiag1(edgesTex, texcoord, float2(-1.0, 1.0), end, k); d.x += float(end.y > 0.9); }\n"
    "    else d.xz = float2(0.0);\n"
    "    d.yw = searchDiag1(edgesTex, texcoord, float2(1.0, -1.0), end, k);\n"
    "    if (d.x + d.y > 2.0) {\n"
    "        float4 coords = float4(-d.x + 0.25, d.x, d.y, -d.y - 0.25) * RT.xyxy + texcoord.xyxy;\n"
    "        float4 c;\n"
    "        c.xy = lzo(edgesTex, coords.xy, int2(-1, 0), k).rg;\n"
    "        c.zw = lzo(edgesTex, coords.zw, int2(1, 0), k).rg;\n"
    "        c.yxwz = decodeDiag(c.xyzw);\n"
    "        float2 cc = float2(2.0) * c.xz + c.yw;\n"
    "        bool2 z = bool2(step2(0.9, d.zw)); if (z.x) cc.x = 0.0; if (z.y) cc.y = 0.0;\n"
    "        weights += areaDiag(areaTex, d.xy, cc);\n"
    "    }\n"
    "    d.xz = searchDiag2(edgesTex, texcoord, float2(-1.0, -1.0), end, k);\n"
    "    if (lzo(edgesTex, texcoord, int2(1, 0), k).r > 0.0) { d.yw = searchDiag2(edgesTex, texcoord, float2(1.0, 1.0), end, k); d.y += float(end.y > 0.9); }\n"
    "    else d.yw = float2(0.0);\n"
    "    if (d.x + d.y > 2.0) {\n"
    "        float4 coords = float4(-d.x, -d.x, d.y, d.y) * RT.xyxy + texcoord.xyxy;\n"
    "        float4 c;\n"
    "        c.x = lzo(edgesTex, coords.xy, int2(-1, 0), k).g;\n"
    "        c.y = lzo(edgesTex, coords.xy, int2(0, -1), k).r;\n"
    "        c.zw = lzo(edgesTex, coords.zw, int2(1, 0), k).gr;\n"
    "        float2 cc = float2(2.0) * c.xz + c.yw;\n"
    "        bool2 z = bool2(step2(0.9, d.zw)); if (z.x) cc.x = 0.0; if (z.y) cc.y = 0.0;\n"
    "        weights += areaDiag(areaTex, d.xy, cc).gr;\n"
    "    }\n"
    "    return weights;\n"
    "}\n"
    "static float searchLength(texture2d<float> searchTex, float2 e, float offset) {\n"
    "    float2 scale = SMAA_SEARCHTEX_SIZE * float2(0.5, -1.0), bias = SMAA_SEARCHTEX_SIZE * float2(offset, 1.0);\n"
    "    scale += float2(-1.0, 1.0); bias += float2(0.5, -0.5);\n"
    "    scale *= 1.0 / SMAA_SEARCHTEX_PACKED_SIZE; bias *= 1.0 / SMAA_SEARCHTEX_PACKED_SIZE;\n"
    "    return lz(searchTex, scale * e + bias).r;\n"
    "}\n"
    "static float searchXLeft(texture2d<float> edgesTex, texture2d<float> searchTex, float2 texcoord, float end, constant K &k) {\n"
    "    float2 e = float2(0.0, 1.0);\n"
    "    while (texcoord.x > end && e.g > 0.8281 && e.r == 0.0) { e = lz(edgesTex, texcoord).rg; texcoord = -float2(2.0, 0.0) * RT.xy + texcoord; }\n"
    "    float offset = -(255.0 / 127.0) * searchLength(searchTex, e, 0.0) + 3.25;\n"
    "    return RT.x * offset + texcoord.x;\n"
    "}\n"
    "static float searchXRight(texture2d<float> edgesTex, texture2d<float> searchTex, float2 texcoord, float end, constant K &k) {\n"
    "    float2 e = float2(0.0, 1.0);\n"
    "    while (texcoord.x < end && e.g > 0.8281 && e.r == 0.0) { e = lz(edgesTex, texcoord).rg; texcoord = float2(2.0, 0.0) * RT.xy + texcoord; }\n"
    "    float offset = -(255.0 / 127.0) * searchLength(searchTex, e, 0.5) + 3.25;\n"
    "    return -RT.x * offset + texcoord.x;\n"
    "}\n"
    "static float searchYUp(texture2d<float> edgesTex, texture2d<float> searchTex, float2 texcoord, float end, constant K &k) {\n"
    "    float2 e = float2(1.0, 0.0);\n"
    "    while (texcoord.y > end && e.r > 0.8281 && e.g == 0.0) { e = lz(edgesTex, texcoord).rg; texcoord = -float2(0.0, 2.0) * RT.xy + texcoord; }\n"
    "    float offset = -(255.0 / 127.0) * searchLength(searchTex, e.gr, 0.0) + 3.25;\n"
    "    return RT.y * offset + texcoord.y;\n"
    "}\n"
    "static float searchYDown(texture2d<float> edgesTex, texture2d<float> searchTex, float2 texcoord, float end, constant K &k) {\n"
    "    float2 e = float2(1.0, 0.0);\n"
    "    while (texcoord.y < end && e.r > 0.8281 && e.g == 0.0) { e = lz(edgesTex, texcoord).rg; texcoord = float2(0.0, 2.0) * RT.xy + texcoord; }\n"
    "    float offset = -(255.0 / 127.0) * searchLength(searchTex, e.gr, 0.5) + 3.25;\n"
    "    return -RT.y * offset + texcoord.y;\n"
    "}\n"
    "static float2 area(texture2d<float> areaTex, float2 dist, float e1, float e2) {\n"
    "    float2 texcoord = float2(SMAA_AREATEX_MAX_DISTANCE) * round(4.0 * float2(e1, e2)) + dist;\n"
    "    texcoord = SMAA_AREATEX_PIXEL_SIZE * texcoord + 0.5 * SMAA_AREATEX_PIXEL_SIZE;\n"
    "    return lz(areaTex, texcoord).rg;\n"
    "}\n"
    "static void cornerH(texture2d<float> edgesTex, thread float2 &weights, float4 texcoord, float2 d, constant K &k) {\n"
    "    float2 leftRight = step(d.xy, d.yx);\n"
    "    float2 rounding = (1.0 - SMAA_CORNER_ROUNDING_NORM) * leftRight;\n"
    "    rounding /= leftRight.x + leftRight.y;\n"
    "    float2 factor = float2(1.0);\n"
    "    factor.x -= rounding.x * lzo(edgesTex, texcoord.xy, int2(0, 1), k).r;\n"
    "    factor.x -= rounding.y * lzo(edgesTex, texcoord.zw, int2(1, 1), k).r;\n"
    "    factor.y -= rounding.x * lzo(edgesTex, texcoord.xy, int2(0, -2), k).r;\n"
    "    factor.y -= rounding.y * lzo(edgesTex, texcoord.zw, int2(1, -2), k).r;\n"
    "    weights *= saturate(factor);\n"
    "}\n"
    "static void cornerV(texture2d<float> edgesTex, thread float2 &weights, float4 texcoord, float2 d, constant K &k) {\n"
    "    float2 leftRight = step(d.xy, d.yx);\n"
    "    float2 rounding = (1.0 - SMAA_CORNER_ROUNDING_NORM) * leftRight;\n"
    "    rounding /= leftRight.x + leftRight.y;\n"
    "    float2 factor = float2(1.0);\n"
    "    factor.x -= rounding.x * lzo(edgesTex, texcoord.xy, int2(1, 0), k).g;\n"
    "    factor.x -= rounding.y * lzo(edgesTex, texcoord.zw, int2(1, 1), k).g;\n"
    "    factor.y -= rounding.x * lzo(edgesTex, texcoord.xy, int2(-2, 0), k).g;\n"
    "    factor.y -= rounding.y * lzo(edgesTex, texcoord.zw, int2(-2, 1), k).g;\n"
    "    weights *= saturate(factor);\n"
    "}\n"
    "fragment float4 smaa_weight(V in [[stage_in]], texture2d<float> edgesTex [[texture(0)]], texture2d<float> areaTex [[texture(1)]], texture2d<float> searchTex [[texture(2)]], constant K &k [[buffer(0)]]) {\n"
    "    float2 pixcoord = in.pos.xy, texcoord = pixcoord * RT.xy;\n"
    "    float4 offset[3];\n"
    "    offset[0] = RT.xyxy * float4(-0.25, -0.125, 1.25, -0.125) + texcoord.xyxy;\n"
    "    offset[1] = RT.xyxy * float4(-0.125, -0.25, -0.125, 1.25) + texcoord.xyxy;\n"
    "    offset[2] = RT.xxyy * (float4(-2.0, 2.0, -2.0, 2.0) * float(SMAA_MAX_SEARCH_STEPS)) + float4(offset[0].xz, offset[1].yw);\n"
    "    float4 weights = float4(0.0);\n"
    "    float2 e = edgesTex.sample(lin, texcoord).rg;\n"
    "    if (e.g > 0.0) {\n"
    "        weights.rg = diagWeights(edgesTex, areaTex, texcoord, e, k);\n"
    "        if (weights.r == -weights.g) {\n"
    "            float2 d; float3 coords;\n"
    "            coords.x = searchXLeft(edgesTex, searchTex, offset[0].xy, offset[2].x, k);\n"
    "            coords.y = offset[1].y;\n"
    "            d.x = coords.x;\n"
    "            float e1 = lz(edgesTex, coords.xy).r;\n"
    "            coords.z = searchXRight(edgesTex, searchTex, offset[0].zw, offset[2].y, k);\n"
    "            d.y = coords.z;\n"
    "            d = abs(round(RT.zz * d - pixcoord.xx));\n"
    "            float2 sqrt_d = sqrt(d);\n"
    "            float e2 = lzo(edgesTex, coords.zy, int2(1, 0), k).r;\n"
    "            weights.rg = area(areaTex, sqrt_d, e1, e2);\n"
    "            coords.y = texcoord.y;\n"
    "            float2 w = weights.rg; cornerH(edgesTex, w, coords.xyzy, d, k); weights.rg = w;\n"
    "        } else e.r = 0.0;\n"
    "    }\n"
    "    if (e.r > 0.0) {\n"
    "        float2 d; float3 coords;\n"
    "        coords.y = searchYUp(edgesTex, searchTex, offset[1].xy, offset[2].z, k);\n"
    "        coords.x = offset[0].x;\n"
    "        d.x = coords.y;\n"
    "        float e1 = lz(edgesTex, coords.xy).g;\n"
    "        coords.z = searchYDown(edgesTex, searchTex, offset[1].zw, offset[2].w, k);\n"
    "        d.y = coords.z;\n"
    "        d = abs(round(RT.ww * d - pixcoord.yy));\n"
    "        float2 sqrt_d = sqrt(d);\n"
    "        float e2 = lzo(edgesTex, coords.xz, int2(0, 1), k).g;\n"
    "        weights.ba = area(areaTex, sqrt_d, e1, e2);\n"
    "        coords.x = texcoord.x;\n"
    "        float2 w = weights.ba; cornerV(edgesTex, w, coords.xyxz, d, k); weights.ba = w;\n"
    "    }\n"
    "    return weights;\n"
    "}\n"
    "fragment float4 smaa_blend(V in [[stage_in]], texture2d<float> colorTex [[texture(0)]], texture2d<float> blendTex [[texture(1)]], constant K &k [[buffer(0)]]) {\n"
    "    float2 texcoord = in.pos.xy * RT.xy;\n"
    "    float4 offset = RT.xyxy * float4(1.0, 0.0, 0.0, 1.0) + texcoord.xyxy;\n"
    "    float4 a;\n"
    "    a.x = blendTex.sample(lin, offset.xy).a;\n"
    "    a.y = blendTex.sample(lin, offset.zw).g;\n"
    "    a.wz = blendTex.sample(lin, texcoord).xz;\n"
    "    if (dot(a, float4(1.0)) < 1e-5) return lz(colorTex, uvc(in.pos.xy, k));\n"
    "    bool h = max(a.x, a.z) > max(a.y, a.w);\n"
    "    float4 blendingOffset = h ? float4(a.x, 0.0, a.z, 0.0) : float4(0.0, a.y, 0.0, a.w);\n"
    "    float2 blendingWeight = h ? a.xz : a.yw;\n"
    "    blendingWeight /= dot(blendingWeight, float2(1.0));\n"
    "    float4 blendingCoord = blendingOffset * float4(RT.xy, -RT.xy) + texcoord.xyxy;\n"
    "    float4 lim = float4(k.rect.xy + 0.5, k.rect.zw - 0.5) * RT.xyxy;\n"
    "    float4 color = blendingWeight.x * lz(colorTex, clamp(blendingCoord.xy, lim.xy, lim.zw));\n"
    "    color += blendingWeight.y * lz(colorTex, clamp(blendingCoord.zw, lim.xy, lim.zw));\n"
    "    return color;\n"
    "}\n";
